"""
Execute a shell command and log the output.
"""
logging.info(f"Executing {task_name}: {command}")

try:
    # Execute the command
    result = subprocess.run(
        command, 
        shell=True, 
        capture_output=True, 
        text=True, 
        timeout=300  # 5 minute timeout
    )

    if result.returncode == 0:
        logging.info(f"Successfully executed {task_name}")
        if result.stdout:
            logging.info(f"Output: {result.stdout.strip()}")
    else:
        logging.error(f"Command failed with return code {result.returncode}")
        if result.stderr:
            logging.error(f"Error: {result.stderr}")

except subprocess.TimeoutExpired:
    logging.error(f"Command timed out after 5 minutes")
except Exception as e:
    logging.error(f"Failed to execute command: {str(e)}")

